-- 0006: seed rows. Plans (contract section 8) and tax_rule_packs
-- rows whose payloads match shared/tax-rules/*.json exactly.
-- Generated from the JSON files; regenerate if a pack changes.
-- Idempotent: inserts use ON CONFLICT to update in place.

insert into public.plans (id, display_name, monthly_price_paise, display_price, ai_calls_per_day, ai_calls_per_month, features) values
  ('free', 'Free', 0, 'Free', 20, null, '["basic calculators", "basic invoice", "basic calendar"]'::jsonb),
  ('personal_plus', 'Personal Plus', 9900, 'Rs 99/month', 100, null, '["higher AI cap", "notice analysis", "vault"]'::jsonb),
  ('business_pro', 'Business Pro', 29900, 'Rs 299/month', 300, null, '["registers", "ITC", "reconciliation", "expenses", "reports"]'::jsonb),
  ('ca_professional', 'CA Professional', 99900, 'Rs 999/month', 1000, null, '["client dashboard foundation", "multi-business"]'::jsonb)
on conflict (id) do update set display_name = excluded.display_name, monthly_price_paise = excluded.monthly_price_paise, display_price = excluded.display_price, ai_calls_per_day = excluded.ai_calls_per_day, ai_calls_per_month = excluded.ai_calls_per_month, features = excluded.features;

-- Pack ay-2026-27 v1 from shared/tax-rules/ay-2026-27.json.
insert into public.tax_rule_packs (ay, version, payload, source, verified, verified_at) values
  ('2026-27', 1, $payload${"assessment_year":"2026-27","basic_exemption":{"new_regime":400000,"old_senior_60_79":300000,"old_super_senior_80_plus":500000,"old_under_60":250000},"effective_from":"2026-04-01","financial_year":"2025-26","id":"ay-2026-27","new_regime":{"cess":0.04,"marginal_relief":true,"rebate_limit":1200000,"rebate_max":60000,"slabs":[[0,0],[400000,0.05],[800000,0.1],[1200000,0.15],[1600000,0.2],[2000000,0.25],[2400000,0.3]],"standard_deduction_salaried":75000},"notes":"Slabs, standard deductions, rebate limits and cess were checked against the secondary sources listed above on 2026-11-16 and match across them. They were NOT checked against the CBDT tax reference tables directly, so verified stays false. Surcharge brackets are the commonly published brackets and were not independently verified in this pass. Every UI using this pack must show a verify on the official portal note. The calculator covers resident individuals under 60 only. Senior citizen slabs, special-rate income (capital gains), and marginal relief above the surcharge thresholds are not modelled. New regime marginal relief just above the rebate limit IS modelled: pre-cess tax is capped at the amount by which taxable income exceeds the rebate limit. Home loan interest cap (Rs 200,000) is carried from the previous app values and was not independently verified in this pass.","old_regime":{"cess":0.04,"deductions":{"80C":150000,"80CCD1B":50000,"80D_parents":25000,"80D_parents_senior":50000,"80D_self_family":25000,"80D_self_family_senior":50000,"home_loan_interest":200000},"rebate_limit":500000,"rebate_max":12500,"slabs":[[0,0],[250000,0.05],[500000,0.2],[1000000,0.3]],"standard_deduction_salaried":50000},"sources":[{"accessed":"2026-11-16","publisher":"TaxGuru","title":"Section 202 vs Section 115BAC: New Tax Regime Under Income-tax Act, 2025","url":"https://taxguru.in/income-tax/section-202-section-115bac-tax-regime-income-tax-act-2025.html"},{"accessed":"2026-11-16","publisher":"Indian Pay Calculator","title":"Income Tax Slabs AY 2026-27 (FY 2025-26)","url":"https://www.indianpaycalculator.in/income-tax-slabs"},{"accessed":"2026-11-16","publisher":"BusinessMust","title":"New Tax Regime Slabs 2026-27: Rates, Rebate and Examples","url":"https://www.businessmust.com/new-tax-regime-slabs-2026-27/"},{"accessed":"2026-11-16","publisher":"Finance Tools Academy","title":"Income Tax Guide India FY 2025-26: Slabs and Deductions","url":"https://www.financetoolsacademy.com/learn/income-tax-guide.html"},{"accessed":"2026-11-16","publisher":"Dhanaay","title":"Income Tax Slabs FY 2026-27","url":"http://dhanaay.com/s/income-tax-slabs"}],"surcharge":[{"above":5000000,"rate":0.1},{"above":10000000,"rate":0.15},{"above":20000000,"rate":0.25},{"above":50000000,"rate":0.37}],"surcharge_cap_new_regime":0.25,"verified":false,"version":1}$payload$, 'shared/tax-rules/ay-2026-27.json v1', false, null)
on conflict (ay, version) do update set payload = excluded.payload, source = excluded.source, verified = excluded.verified, verified_at = excluded.verified_at;

-- Pack gst v1 from shared/tax-rules/gst.json.
insert into public.tax_rule_packs (ay, version, payload, source, verified, verified_at) values
  ('gst', 1, $payload${"council":"56th GST Council, 3 September 2025","effective_from":"2025-09-22","id":"gst","interest_basis":"Net cash tax: interest is charged on the tax paid in cash after input tax credit, not on the gross liability.","interest_note":"Simple interest at 18% per annum on the net cash tax, pro rated by days delayed divided by 365. The 24% rate applies only when the notice states section 50(3). Estimator only; verify on the GST portal.","interest_pa":0.18,"interest_pa_section_50_3":0.24,"legacy_note":"12% and 28% were withdrawn for most supplies from 22 September 2025. Use them only to verify invoices dated before that date, and only when explicitly requested.","legacy_rates":[12,28],"penalty_no_fraud":{"minimum":10000,"note":"Rough estimator input only, carried from the previous app values; not a demand computation. Verify on the official portal.","rate":0.1},"notes":"Current rates were checked against the secondary sources listed above on 2026-11-16. They agree: from 22 September 2025 the main GST rates are 5% (merit) and 18% (standard), with 40% for a short de-merit list and 0% for exempt supplies, under Notification 9/2025-Central Tax (Rate) following the 56th GST Council decisions. The 12% and 28% rates were withdrawn for most supplies and are kept here as legacy rates for invoices dated before 22 September 2025 only. The notification text itself was not read directly, so verified stays false. The rate for a specific supply depends on its HSN or SAC code and conditions: verify on the CBIC GST rate finder or the GST portal before billing.","notification":"Notification 9/2025-Central Tax (Rate), w.e.f. 22 September 2025","rates":[0,5,18,40],"rates_detail":[{"label":"Exempt / nil rated","rate":0,"status":"current"},{"label":"Merit rate","rate":5,"status":"current"},{"label":"Standard rate","rate":18,"status":"current"},{"label":"De-merit rate (short list: tobacco, pan masala, aerated drinks, luxury cars, yachts, betting and gaming)","rate":40,"status":"current"}],"sources":[{"accessed":"2026-11-16","publisher":"ZoolTools","title":"GST 2.0 Slabs Explained: What Changed in September 2025","url":"https://www.zooltools.com/guides/gst-slabs-explained"},{"accessed":"2026-11-16","publisher":"BookMyCA","title":"GST Rates 2026: 5%, 18% and 40% Slabs After GST 2.0","url":"https://www.bookmyca.in/services/gst/gst-rates-2026"},{"accessed":"2026-11-16","publisher":"FundRaksha","title":"GST Calculator: Add or Remove GST, CGST SGST IGST","url":"https://www.fundraksha.com/calculators/gst-calculator"},{"accessed":"2026-11-16","publisher":"AppSaaz","title":"GST 2.0: the 5%, 18% and 40% rates and what moved for online brands","url":"https://www.getsaaz.app/guides/gst-rates-2025-reform"}],"special_rates":[{"label":"Gold, silver and platinum","rate":3,"status":"current"}],"split":{"interstate":["igst"],"intrastate":["cgst","sgst"],"note":"Intrastate supplies split the tax equally between CGST and SGST. Interstate supplies charge the full tax as IGST."},"verified":false,"version":1}$payload$, 'shared/tax-rules/gst.json v1', false, null)
on conflict (ay, version) do update set payload = excluded.payload, source = excluded.source, verified = excluded.verified, verified_at = excluded.verified_at;

-- Pack due-dates v1 from shared/tax-rules/due-dates.json.
insert into public.tax_rule_packs (ay, version, payload, source, verified, verified_at) values
  ('due-dates', 1, $payload${"due_dates":[{"applicable_to":["salaried","freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"tds","frequency":"monthly","key":"tds_deposit","label":"TDS/TCS deposit","rule":"7th of following month","schedule":{"day":7,"kind":"monthly","offset_months":1}},{"applicable_to":["partnership","llp","private_limited","other"],"category":"payroll","frequency":"monthly","key":"pf_esi","label":"PF and ESI deposit","rule":"15th of following month","schedule":{"day":15,"kind":"monthly","offset_months":1}},{"applicable_to":["freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"gst","frequency":"monthly","key":"gstr1","label":"GSTR-1","rule":"11th of following month","schedule":{"day":11,"kind":"monthly","offset_months":1}},{"applicable_to":["freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"gst","frequency":"monthly","key":"gstr3b","label":"GSTR-3B","rule":"20th of following month","schedule":{"day":20,"kind":"monthly","offset_months":1}},{"applicable_to":["freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"gst","frequency":"quarterly","key":"gstr1_qrmp","label":"GSTR-1 (QRMP)","rule":"13th of month after the quarter","schedule":{"day":13,"kind":"quarter_end","offset_months":1}},{"applicable_to":["freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"gst","frequency":"quarterly","key":"gstr3b_qrmp","label":"GSTR-3B (QRMP)","rule":"22nd or 24th of month after the quarter, depending on state (22nd used here as the earlier date)","schedule":{"day":22,"kind":"quarter_end","offset_months":1}},{"applicable_to":["freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"gst","frequency":"yearly","key":"gstr9","label":"GSTR-9 annual return","note":"Annual return for the preceding financial year. Verify applicability and turnover threshold on the GST portal.","rule":"31 December following the financial year","schedule":{"day":31,"kind":"yearly","month":12}},{"applicable_to":["individual","salaried","freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"income_tax","frequency":"yearly","key":"advance_tax_1","label":"Advance tax instalment 1 (15% cumulative)","rule":"15 June","schedule":{"day":15,"kind":"yearly","month":6}},{"applicable_to":["individual","salaried","freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"income_tax","frequency":"yearly","key":"advance_tax_2","label":"Advance tax instalment 2 (45% cumulative)","rule":"15 September","schedule":{"day":15,"kind":"yearly","month":9}},{"applicable_to":["individual","salaried","freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"income_tax","frequency":"yearly","key":"advance_tax_3","label":"Advance tax instalment 3 (75% cumulative)","rule":"15 December","schedule":{"day":15,"kind":"yearly","month":12}},{"applicable_to":["individual","salaried","freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"income_tax","frequency":"yearly","key":"advance_tax_4","label":"Advance tax instalment 4 (100% cumulative)","rule":"15 March","schedule":{"day":15,"kind":"yearly","month":3}},{"applicable_to":["individual","salaried","freelancer","sole_proprietor","other"],"category":"income_tax","frequency":"yearly","key":"itr_individual","label":"ITR filing (individual, no audit)","rule":"31 July","schedule":{"day":31,"kind":"yearly","month":7}},{"applicable_to":["sole_proprietor","partnership","llp","private_limited","other"],"category":"income_tax","frequency":"yearly","key":"tax_audit","label":"Tax audit report","rule":"30 September","schedule":{"day":30,"kind":"yearly","month":9}},{"applicable_to":["sole_proprietor","partnership","llp","private_limited","other"],"category":"income_tax","frequency":"yearly","key":"itr_audit","label":"ITR filing (audit cases)","rule":"31 October","schedule":{"day":31,"kind":"yearly","month":10}},{"applicable_to":["freelancer","sole_proprietor","partnership","llp","private_limited","other"],"category":"tds","frequency":"quarterly","key":"tds_return","label":"TDS return (quarterly)","rule":"31 July, 31 October, 31 January and 31 May for the four quarters","schedule":{"day":31,"kind":"fixed_months","months":[1,5,7,10]}}],"effective_from":"2025-04-01","id":"due-dates","notes":"Standard rules only, checked against the secondary sources listed above on 2026-11-16. Due dates are extended by notification from time to time and a date does not move for a Sunday or holiday unless notified. Every UI using this pack must show a verify on the official portal note. QRMP GSTR-3B is the 22nd or 24th depending on state; this pack uses the 22nd as the earlier date and says so in the rule text. TDS deposit, PF/ESI deposit, and tax audit report entries are carried from the previous app values and were not independently verified in this pass.","sources":[{"accessed":"2026-11-16","publisher":"ComplyKart","title":"GST Return Filing in India: A Practitioner's Guide","url":"https://www.complykart.com/blog/gst-return-filing-complete-guide"},{"accessed":"2026-11-16","publisher":"Indian Business Tools","title":"GST Due Date Calendar: Monthly and Quarterly GSTR-1, 3B, CMP-08","url":"https://www.indianbusinesstools.com/tools/gst-return-due-date-calendar"},{"accessed":"2026-11-16","publisher":"Finance Tools Academy","title":"Income Tax Guide India FY 2025-26: Slabs and Deductions","url":"https://www.financetoolsacademy.com/learn/income-tax-guide.html"},{"accessed":"2026-11-16","publisher":"Dhanaay","title":"Income Tax Slabs FY 2026-27","url":"http://dhanaay.com/s/income-tax-slabs"}],"verified":false,"version":1}$payload$, 'shared/tax-rules/due-dates.json v1', false, null)
on conflict (ay, version) do update set payload = excluded.payload, source = excluded.source, verified = excluded.verified, verified_at = excluded.verified_at;
